import base64, io, glob, html, os
from PIL import Image
os.chdir(os.path.dirname(os.path.abspath(__file__)))
img = {}
for f in sorted(glob.glob('frame_*.png')):
    im = Image.open(f).convert('RGB')
    if im.width > 1000:
        im = im.resize((1000, int(im.height * 1000 / im.width)), Image.LANCZOS)
    b = io.BytesIO(); im.save(b, 'JPEG', quality=80, optimize=True)
    img[f[:-4]] = (base64.b64encode(b.getvalue()).decode(), im.width, im.height)
F = lambda k: [x for x in img if x.startswith('frame_' + k)][0]

parts = [
 ('around', 'Getting around', [
  (F('0000_'), 'Dashboard', 'The home screen. The strip at the top shows today at a glance: new orders waiting, orders being prepared, orders today and revenue today with the change against yesterday. Below it, <b>Needs your attention</b> lists orders that need a decision, <b>Quick actions</b> jumps to any page, and the week chart shows revenue per day.'),
  (F('0005_'), 'The menu', 'Press the ☰ button or Ctrl+K to open the full menu. Pages are grouped into Operations, Basic information, Reports, Settings and User management. Type in the search box to jump straight to a page, a product or a customer.'),
 ]),
 ('sell', 'Selling', [
  (F('0010_'), 'POS', 'Ring up a sale in seconds. Pick the order type (in person, take-away, delivery), choose a table or a walk-in customer, tap dishes on the left and they land in the ticket on the right with quantities, tax and total. <b>Save as open</b> keeps the table running; <b>Close &amp; pay</b> settles it in cash or card and prints the receipt and the kitchen ticket.'),
  (F('0018_'), 'POS on a tablet', 'The same till laid out for a tablet held by a waiter: categories across the top, dishes in a grid, and a floating total that opens the ticket. Everything a waiter needs is one tap away.'),
  (F('0021_'), 'Tables', 'The dining room as it stands, and the tool that arranges it. Across the top, how much of the house is free and how much is sitting \u2014 <b>44 free, 27 occupied</b> tells a host where to put the next party before they have finished asking. Each salon is a card carrying its name, how many tables it holds and how many people those seat; inside it every table shows its number, its seats and what is happening at it: green for free, warm for occupied, a dot for an order still open. Under a seated table is who is there and for how long \u2014 <b>Walk-in</b> when the waiter seated them, <b>QR</b> when the guests scanned the code and ordered from their own phones \u2014 and a clock running since they sat, which is how a forgotten table becomes obvious from across the room. Tap any table to open its running bill and add a round.<br><br><b>Every table can carry its own QR code.</b> Print one code per table from Table QR codes and stick it on the table: the code knows both the shop and the table, so a scan opens your menu for that table alone. The guests order from their own phones straight onto that table’s bill, call a waiter or ask for the bill without anyone coming over, and the board marks the table <b>QR</b> so the floor knows the order came from the guests rather than a waiter.<br><br>The floor is drawn, not typed. Drag a salon by the grip in its corner to move it and pull its edge to resize it; the tables inside travel with it, and a salon made smaller pulls its own tables back in rather than stranding them. Salons cannot be dropped on top of one another, so the plan always matches a room a waiter could walk through. <b>Add salon</b> and <b>Add table</b> build it out, the pencil renames, the bin removes, and every move is saved the moment you let go \u2014 there is no Save button to forget.'),
  (F('0200_'), 'Table QR codes', 'Print one code per table. A scan opens the menu for that table: the guest orders, calls a waiter or reserves it. Choose the size, add your own card wording, download one card or print them all.'),
  (F('0171_0171'), 'Order assistant and product printers', 'Type an order in plain words, for example "2 lamb ribs table 3", and the assistant adds it to that table. Behind it, <b>Product printers</b> decides which kitchen printer each dish goes to: kitchen, bar or none, while the cashier receipt always prints at the till.'),
 ]),
 ('orders', 'Orders and guests', [
  (F('0028_'), 'Live orders', 'The board refreshes on its own. New orders arrive on the left with the customer, the lines and any note; press <b>Accept</b> to send them to the kitchen or <b>Reject</b> to turn them down. Orders move from New to Cooking to Ready as the kitchen works.'),
  (F('0211_'), 'Kitchen display', 'A screen for the pass instead of a printer. Tickets arrive in two lanes — <b>New</b> and <b>Cooking</b>, oldest first, because the oldest ticket is always the next job — and each one counts up from the moment the food was ordered, its edge turning amber and then red as it runs late against your own preparation time. A cook ticks a line off as it is plated and presses the one big button: <b>Start cooking</b>, then <b>Ready</b>. What makes it a kitchen screen rather than a list of web orders is where the tickets come from: online orders AND every round a waiter rings up at a table, which a printer alone never shows you. Each station can be filtered to its own items using your product printer map, so the bar screen shows drinks and the grill screen shows grills. It rings when something new arrives, keeps the display awake, and goes full screen on a tap.'),
  (F('0032_'), 'Take-out and dine-in board', 'Every accepted order with its table or pick-up details. Mark an order <b>Delivered</b> once it reaches the guest, assign a courier for delivery orders, or share a live location link with the customer.'),
  (F('0056_'), 'Delivery hand-over', 'Orders that leave the building. Each card shows the customer, the address and the courier status. <b>Print invoice</b> gives the rider a delivery note; <b>Mark ready</b> tells the customer the order is on its way.'),
  (F('0035_'), 'Reservations', 'Bookings from the website, the table QR code and phone calls in one list, by day and time, with guests, table and the note the guest left. Confirm, cancel, or press <b>Seat now</b> when the party arrives; the table on the floor plan turns occupied.'),
  (F('0143_'), 'Table chat', 'Guests who scan the table QR code can message the house. Every table with a conversation appears here with the latest message and an unread counter.'),
  (F('0146_'), 'Answering a table', 'Open a table to see the conversation. Reply with text, a photo or a voice note; the guest sees it on their phone. Typical use: "Can we have the bill please?" answered from the till without walking over.'),
  (F('0204_'), 'What your customers see', 'The customer app at orderorange.com: your shop among the restaurants, markets and pharmacies near you, with search by dish or craving, categories, favourites and a one-tap order. Guests order for delivery or pickup, and the same app opens from a table QR code. Fourteen languages, no commission on the order.'),
  (F('0204_'), 'Smart search', 'The search box on the customer home understands people, not just spelling. One query searches restaurants and dishes together, in any of the fourteen languages: "kabab", "kebab" and "كباب" find the same plate. It forgives typos, words typed on the wrong keyboard, Arabizi digits like "3" for ع, merged or split words, and it suggests results while the guest is still typing. When nothing matches it offers a "Did you mean" correction; recent searches of the guest and trending cravings sit under the box before they type.'),
  (F('0205_'), 'OrderOrange AI', 'One assistant, working both sides of the counter.<br><br><b>For your guests</b>, the sparkle button on the shop page takes an order from start to finish in ordinary language, by typing or by speaking. \u201c2 pizzas and a cola to Al Mouj\u201d becomes a basket, an address and a checkout in one sentence \u2014 quantities, sizes, notes and the address read together rather than asked for one at a time. It answers the questions people actually ask: \u201cdo you have pizza\u201d, \u201chow much is the delivery\u201d, \u201cwhere is my order\u201d, \u201ccancel it\u201d, even \u201cwhat can I get for five rials\u201d. It replies in whatever language the guest wrote in, across fourteen of them, and it forgives spelling \u2014 a misspelled kebab still finds the kebab. It never invents a dish: something it cannot find is asked about, not guessed, and it only ever offers real dishes at today\u2019s prices from kitchens that are open.<br><br><b>For your staff</b>, the same brain sits inside the POS as the order assistant. Key or dictate a whole ticket \u2014 \u201c2 koobideh, 1 cola, table 5\u201d \u2014 and it lands on that table, which is far faster than hunting a grid at a rush. It answers questions about the shop at the till, does the arithmetic and the clock maths a cashier ends up doing anyway, and Ctrl+K searches pages, products, customers and orders from anywhere in the portal.<br><br><b>And it tells you what people wanted.</b> Every question a guest typed is kept and grouped by the address it came from, so you can read, in their words, what was asked for and not found \u2014 the dish to put on the menu next month is usually in that list.<br><br><b>It runs on OrderOrange\u2019s own vocabulary, not an outside AI service.</b> Nothing your guests type leaves the platform, there is no per-message bill, it keeps working when somebody else\u2019s service is down, and the same sentence always produces the same basket \u2014 which matters when it is taking real money.'),
  (F('0225_'), 'Instagram', 'Your restaurant\u2019s Instagram, posted from the same place you run the kitchen. Connect the account once; from then on pick a dish photo from the menu or any picture, write the caption, tap the ready hashtags and press <b>Post to Instagram</b>. The card on the right shows the connected account, how long its token has left (it renews itself while you keep posting) and your recent posts. Instagram allows 100 posts a day per account; the counter under the button keeps you inside it.'),
  (F('0226_'), 'Scheduled posts', 'Plan a post now and OrderOrange publishes it at the hour you choose. Add a photo or pick a dish, write the caption, then set the day and the time — or use the shortcuts: <b>Tonight 19:00</b>, <b>Tomorrow 12:00</b>, <b>Tomorrow 19:00</b>. <b>The plan</b> lists everything waiting and everything that already went out, so a week of posts can be set up on a quiet Monday morning. The <b>Menu poster</b> page draws a 1080\u00d71350 picture of your dishes and prices that can be posted, scheduled or downloaded.'),
  (F('0224_'), 'Today\u2019s dishes on WhatsApp', 'Your dishes, delivered to the guest\u2019s WhatsApp as a swipeable carousel: a photo, the name, the price and an <b>Order now</b> button on every card. A tap opens the order with the OrderOrange assistant, so a message becomes a sale in three touches. The cards come straight from your menu — the same photos and prices your app shows — and go out to guests who have opted in, at the hour you choose.'),
  (F('0227_'), 'Loyalty', 'Reward the guests who keep coming back. Set the rate — say <b>10 points per 1 OMR</b> — what a reward costs and what it is worth, a welcome gift for the first visit, and the lifetime points that make a guest <b>Silver</b> or <b>Gold</b>. From then on the points arrive by themselves: every order paid at the till, closed at a table or delivered credits the guest, once, as long as the guest is on the order rather than the walk-in. The four tiles count the members and the tier mix, what the points on their cards would cost you, what has already been given back, and thirty days of earning as a bar chart. <b>Almost there</b> lists the guests one visit from a reward and <b>Gone quiet</b> the regulars who have not been in for a month — each with a WhatsApp message ready to send. Underneath, two panels refresh themselves every ten seconds: <b>Online now</b> — who is on your store page or sitting at a table with an open tab this minute — and <b>Open invoices</b>, every bill not yet paid with the guest\u2019s points beside it, so the till can offer a reward before the money is taken.'),
  (F('0228_'), 'A guest\u2019s card', 'Everything about one regular on a single card. The ring fills towards the next reward and turns the colour of their tier; beside it sit the visits, the lifetime points, what they have already redeemed, the last time they came and — for a guest still climbing — how many points to Silver or Gold. When the balance covers a reward the card glows and says what it is worth. Three actions follow: <b>Ring up a visit</b> turns an amount into points for a sale that was not rung up on the till, <b>Use 100 pts</b> hands the reward over (the page throws confetti, the balance drops), and <b>Adjust</b> corrects a balance with a reason that is kept. <b>Message on WhatsApp</b> opens a chat with the text already written. Below is every movement on that card — earned, reward, welcome gift, adjustment — with the amount, the note, who did it and when; on the right, the podium of your top three regulars and the rest of the leaderboard.'),
  (F('0201_'), 'Surveys', 'Ask guests a few multiple-choice questions after their visit and read the answers here. Switch a survey on to show it to guests; each question can allow one answer or several.'),
 ]),
 ('menu', 'Your menu', [
  (F('0089_'), 'Products', 'Categories on top, dishes below, each with photo, price and availability. The counters show how many products are available, sold out or marked popular. Add a category or a product from the buttons at the top right.'),
  (F('0171_0172'), 'Editing a product', 'Up to four photos, a name in Arabic plus any other languages, a description, the category, price, discount, sort order and the ingredients that link it to your stock. Three options decide where it shows: <b>Available</b> (can be ordered now), <b>Popular</b> (starred on the menu) and <b>In-store only</b> (kept off the public web menu but still on the POS and the table QR menu). Days and hours limit when it can be ordered. A dish can also live on a schedule: pick the days of the week and the hours it may be ordered, so a breakfast plate disappears at noon and a Friday special only appears on Fridays, and set a lead time in days for food that must be ordered ahead.'),
  (F('0082_'), 'Recipes', 'Link each dish to the materials one portion uses. The card shows the ingredient count, the cost of a portion and the margin against the selling price, so you know which dishes make money. Dishes without a recipe are marked so you can add them.'),
  (F('0038_'), 'Discount codes', 'Your own codes, valid only at your store. Each code has a rule: first order, a minimum number of items, a minimum spend, a number of orders this month, or happy-hour days and times. Set a cap per order, an end date and a usage limit, and switch a code on or off with one tap.'),
 ]),
 ('money', 'Money', [
  (F('0048_'), 'Bills and expenses', 'Rent, electricity, gas, internet, salaries and every other bill your store pays. The tiles show the total, what is unpaid and what is overdue; the list shows due dates and days late. Mark a bill paid, edit it, or set it to repeat monthly.'),
  (F('0065_'), 'Purchases', 'Receive stock from a supplier: pick the materials, enter quantity and cost per unit, and press <b>Receive stock</b>. Pay in cash or card now, or later in one or several installments. Templates save a regular order so a weekly delivery is two taps.'),
  (F('0208_'), 'Receiving stock', 'A purchase in three taps. The bar at the top takes a <b>code or barcode</b> — from a scanner, a phone camera or the keyboard — and a shorthand like <b>7*20</b> means twenty of material number 7. Below it the shelf is laid out as tiles, each with its number, cost and unit; tap a tile to add a line, tap again to add one more. The basket on the right fills in quantity, cost per unit and line total, with the supplier, the invoice number and its date above; <b>Templates</b> replays a regular order and <b>Save as template</b> makes one. Choose cash or card, or <b>Later / installments</b>, and press <b>Receive stock</b>: the shelf, the supplier ledger and the bills are all updated at once.'),
  (F('0209_'), 'Paying later or in instalments', 'Not every supplier is paid on the spot. <b>Pay now</b> settles the invoice in full; <b>Pay later</b> parks it for one payment on a date you pick; <b>Installments</b> splits it into 2, 3, 4 or 6 steps, weekly or monthly, and shows the exact dates and amounts before you commit. The method — cash, card, transfer, cheque — can be fixed now or left as <b>Decide when paying</b>, so each step records how it was actually settled. Everything lands in Bills and purchases, where the open steps wait with their due dates and a single press marks one paid.'),
  (F('0220_'), 'Warehouses map', 'Where your stock actually is, drawn as a map rather than a list. Every place is a card you drag into position — a supplier, a delivery van, the main store, a cold room, the kitchen, the bar, your guests — wearing the picture you chose for it, and a dashed line from one card to the next says <b>this feeds that</b>. The materials page stays the single truth about how much you own; the map only splits that number by place, and anything you have not put anywhere yet stays visible as <b>Not in a place yet</b> so the two always reconcile. Tap a place to see what it holds; below the map, <b>Move stock</b> takes any quantity from one place to another and every move is logged with who did it and why.'),
  (F('0221_'), 'Adding a place', 'A place is a name, a picture and a kind. Ten pictures cover a real supply chain — factory, truck, warehouse, store, restaurant, kitchen, cold room, freezer, bar, customers — and the kind (main store, dry store, cold room, freezer, kitchen, bar, branch) is what the reports group by. One place is the <b>default</b>: where stock lands when nothing else is named. New places appear on the map in a loose grid so they never pile up; drag them where you like, and the layout is remembered for every screen size.'),
  (F('0220_'), 'Central warehouse for branches', 'If you run more than one business, mark one place as the <b>central warehouse</b> — the dark card on the map — and every branch you own sees it: a dark card in its own bar with what it holds and what it is worth. A branch pulls from it by choosing it under <b>From</b>; head office pushes by choosing <b>Branch: …</b> under <b>To</b>. This is the one move that changes ownership: the quantity leaves the central store\u2019s materials, is added to the branch\u2019s own materials (matched by name and unit, created if the branch never stocked it), and lands in the branch\u2019s default place — so each branch keeps its own true count, and both shops get a line in their log.'),
  (F('0223_'), 'Waste', 'What was thrown away, what it cost, and why. Record a write-off in seconds: a material or a finished dish, how much, and one of eight reasons — spoiled, expired, broken, over-made, staff meal, complaint, training, other. Recording takes it off the shelf; a dish also takes its recipe off the shelf and is valued at what its materials cost. The tiles at the top say what the last 7, 30 or 90 days threw away, what share of your stock that is, and the biggest cause; <b>Where it goes</b> and <b>Most wasted</b> point at what to fix first, and any entry can be undone with one press.'),
  (F('0070_'), 'Payments to suppliers', 'Everything still owed to suppliers, oldest first, with the installment step and how many days late. Press <b>Pay</b> on a line to settle it; the tiles above track unpaid, overdue and paid this month.'),
  (F('0212_'), 'Invoices', 'An invoice is never quietly edited. This is the register of every one you have issued \u2014 number, time, customer, how many items, total and where the order got to \u2014 searchable by number and filtered by date. Two actions sit on each row: the pencil <b>replaces</b> the invoice with a corrected copy, and the cross <b>cancels</b> it. Both ask for a reason, and both leave the original where it was.'),
  (F('0213_'), 'Cancelled invoices', 'What was taken back, and by whom. Each row keeps the invoice number, who added it and when, who removed it and when, the total that was on it, the reason the person typed, and the number of the invoice that replaced it \u2014 or a dash when nothing did. This is the page an accountant asks for when the numbering has a gap in it, and the reason it can always be answered. Excel and A4 print, like every other list.'),
  (F('0214_'), 'What changed on an invoice', 'A correction, shown as a correction. The old number and the new one sit side by side with who made the change, when, and the note they left; underneath, the invoice <b>before</b> and <b>after</b> line by line, with what was added picked out in green and the new total against the old one. Months later the question is never \u201cwas this edited?\u201d but \u201cwhat exactly changed, and why\u201d \u2014 and this answers it without anyone having to remember.'),
  (F('0074_'), 'Payroll', 'Run salaries for a month. Each team member shows their role, hours clocked and salary; pay one person or <b>Pay everyone</b>. The tiles show what is expected, paid and remaining.'),
  (F('0045_'), 'Contracts', 'Standing supply agreements for regular customers such as canteens and clubs: products per month, deliveries per month and the monthly amount. Email the contract, print it, or send a signing link.'),
 ]),
 ('team', 'Your team', [
  (F('0139_'), 'Users and roles', 'Give each team member their own login. Every person has a role: owner, manager, cashier, kitchen, waiter or one of your own roles, and only sees the pages that role opens. Switch a login off without deleting it.'),
  (F('0140_'), 'Roles and permissions', 'Exactly what each role can do, page by page: point of sale, live orders, cancelling orders, invoices, reports and so on. Adjust a preset or create your own role such as Accountant.'),
  (F('0142_'), 'Team activity', 'Who is online now, who is offline, their last login and the page each person is on. The history column opens the pages a person visited.'),
  (F('0167_'), 'Team chat', 'Private one-to-one messages between team members: text, photos, voice notes and location. Unread counts show on the contact list.'),
  (F('0077_'), 'Attendance', 'Staff press <b>I\'m here</b> when they arrive and again when they leave; the position is recorded with each press so the owner sees they clocked in at the shop. Leave requests (hourly or daily) go to the owner for approval and feed the payroll.'),
  (F('0042_'), 'Calendar', 'Meetings, deliveries, deadlines and notes the whole team sees, by month, week or day, with a reminder when it matters.'),
 ]),
 ('reports', 'Reports', [
  (F('0100_'), 'Daily report', 'One day, every invoice in full: pick the day, read the totals for invoices, revenue, items sold and cancellations, and open any invoice to see exactly what was on it. Export to Excel or print on A4.'),
  (F('0104_'), 'Product report', 'Which dishes sell, and what each one brings in. Four figures across the top — dishes sold, revenue, how many different dishes moved at all, and the average price they went out at — over today, seven days, thirty days, a year, or any two dates you pick. Below them the <b>top five</b> as bars you can read at a glance, each showing both what it earned and how many went, because the dish that sells most and the dish that earns most are rarely the same one. Then <b>every dish</b> in a table: quantity, average price, revenue and the share of your takings it accounts for, filterable by name. Excel and A4 print sit in the corner of every view.'),
  (F('0215_'), 'Consumption', 'The product report says what you sold; this says what it cost you to sell it. Every order in the period is run back through its recipe, so the figures are worked out rather than guessed: the material cost of the period, how many orders were counted into it, and how many different materials moved. <b>Costliest dishes</b> ranks by the money the ingredients consumed, not by menu price \u2014 which is how a popular, cheap-looking dish turns out to be the expensive one, and why a price list is sometimes worth rewriting. <b>Material by material</b> then shows how much of each went, what it was worth, and how many days of it are left at the current rate: \u201cLamb \u00b7 1 day left\u201d reaches you before the kitchen does. Seven, thirty or ninety days, Excel and A4 print.'),
 ]),
 ('setup', 'Setup', [
  (F('0170_'), 'Store settings', 'Your profile and languages, opening hours, delivery terms, location on the map, contact details, the short web address of your store page, kitchen language for tickets and the photos shown to customers.'),
  (F('0203_'), 'More than one business', 'One account can own several businesses, so a large restaurant with many branches runs connected under one login. Add a branch, a second restaurant, café or shop from the store menu: choose its type, name and cuisine, pin it on the map, and it opens under the same login. The chooser appears at sign-in and the top bar switches between them at any time.'),
  (F('0206_'), 'Working offline', 'OrderOrange can work offline. For shops where the internet drops or is not there at all, an offline edition of the POS keeps selling, printing kitchen tickets and receipts, and holding the day’s orders on the shop PC; everything is sent to the cloud the moment the connection returns, so reports, the customer app and the other branches catch up automatically. It is switched on per shop: open Support, press New ticket, choose Technical problem and write “Offline” as the subject.'),
  (F('0207_'), 'Developer API', 'Everything the partner app does, your own code can do too. A REST API over HTTPS with the same login: read and write the menu, orders, tables, reservations, customers, bills and reports of your store, in JSON, with verified examples in curl, JavaScript, C# and Python. It is how a CRM, an accounting package, a kitchen screen or a chain’s head-office system connects to OrderOrange. Free with every partner account.'),
  (F('0209_'), 'Your currency', 'Pick the symbol your prices wear — OMR, the rial glyph, \u062f.\u0625, \u20b9, \u0024, \u20ac, or type your own. It is a setting, not a conversion: the figures stay exactly as you typed them and only the symbol beside them changes, everywhere at once \u2014 the POS, invoices, every report and export, the kitchen screen and the printed receipt. That is what lets a shop in any country run OrderOrange in its own money.'),
  (F('0109_'), 'Invoice designer', 'Craft the printed receipt: choose a template, upload the logo, set fonts and sizes, write the tagline, thank-you and promotion lines. The live preview on the right updates as you type.'),
  (F('0126_'), 'Receipt preview', 'The full designer with the receipt rendered at 80, 100 or 125 percent, including the QR code guests scan to verify the bill.'),
 ]),
]

def sec(id, title, items):
    h = f'<section id="{id}"><h2>{html.escape(title)}</h2>'
    for k, t, d in items:
        b, w, hh = img[k]
        h += (f'<article><h3>{html.escape(t)}</h3><p>{d}</p>'
              f'<figure><img src="data:image/jpeg;base64,{b}" width="{w}" height="{hh}" alt="{html.escape(t)}" loading="lazy"></figure></article>')
    return h + '</section>'

toc = ''.join(f'<a href="#{i}">{html.escape(t)}</a>' for i, t, _ in parts)
body = ''.join(sec(i, t, items) for i, t, items in parts)
count = sum(len(items) for _, _, items in parts)
css = """
:root{--bg:#FFFCF7;--ink:#221B14;--muted:#7A6E61;--line:#EADFD0;--panel:#FFF6EC;--accent:#FF5A00;--accent-deep:#C24500;--frame:#F3EBE1}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){--bg:#16110C;--ink:#F4ECE2;--muted:#B3A595;--line:#332A20;--panel:#23190F;--accent:#FF7A2A;--accent-deep:#FFA36B;--frame:#2A2118}}
:root[data-theme="dark"]{--bg:#16110C;--ink:#F4ECE2;--muted:#B3A595;--line:#332A20;--panel:#23190F;--accent:#FF7A2A;--accent-deep:#FFA36B;--frame:#2A2118}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.55 "Source Sans 3",system-ui,"Segoe UI",Arial,sans-serif}
header{position:sticky;top:0;z-index:5;background:var(--bg);border-bottom:1px solid var(--line)}
.bar{max-width:960px;margin:0 auto;padding:10px 16px;display:flex;align-items:center;gap:12px}
.mark{width:30px;height:30px;border-radius:9px;background:var(--accent);display:grid;place-items:center;color:#fff;font:700 15px Sora,sans-serif;flex:none}
.bar b{font:600 15px Sora,sans-serif}
.bar span.site{color:var(--muted);font-size:13px;margin-inline-start:auto;white-space:nowrap}
nav{max-width:960px;margin:0 auto;padding:0 16px 10px;display:flex;gap:6px;overflow-x:auto;scrollbar-width:none}
nav::-webkit-scrollbar{display:none}
nav a{flex:none;font:600 12.5px/1 "Source Sans 3",sans-serif;letter-spacing:.2px;color:var(--ink);text-decoration:none;border:1px solid var(--line);border-radius:999px;padding:7px 12px;background:var(--panel)}
nav a:hover,nav a:focus-visible{border-color:var(--accent);color:var(--accent-deep);outline:none}
main{max-width:960px;margin:0 auto;padding:22px 16px 60px}
.lead{max-width:62ch;margin:0 0 6px}
.lead h1{font:700 clamp(26px,4.5vw,36px)/1.1 Sora,sans-serif;margin:0 0 10px;text-wrap:balance;letter-spacing:-.3px}
.lead p{color:var(--muted);margin:0;font-size:17px}
.lead .meta{display:flex;gap:14px;flex-wrap:wrap;margin-top:14px;font-size:13px;color:var(--muted)}
.lead .meta i{font-style:normal;color:var(--accent-deep);font-weight:600}
section{margin-top:38px;scroll-margin-top:96px}
h2{font:700 clamp(20px,3vw,24px)/1.2 Sora,sans-serif;margin:0 0 6px;padding-bottom:8px;border-bottom:2px solid var(--accent);display:inline-block}
article{margin-top:22px}
h3{font:600 18px/1.25 Sora,sans-serif;margin:0 0 6px;text-wrap:balance}
article p{margin:0 0 12px;max-width:68ch}
article p b{font-weight:600;color:var(--accent-deep)}
figure{margin:0;background:var(--frame);border:1px solid var(--line);border-radius:14px;padding:8px}
figure img{display:block;width:100%;height:auto;border-radius:8px}
footer{max-width:960px;margin:0 auto;padding:0 16px 40px;color:var(--muted);font-size:13px}
@media (prefers-reduced-motion:no-preference){html{scroll-behavior:smooth}}
"""
page = f'''<title>OrderOrange Partner Guide</title>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Sora:wght@600;700&family=Source+Sans+3:ital,wght@0,400;0,600;1,400&display=swap">
<style>{css}</style>
<header><div class="bar"><span class="mark">O</span><b>OrderOrange Partner Guide</b><span class="site">partner.orderorange.com</span></div>
<nav>{toc}</nav></header>
<main>
<div class="lead"><h1>Run your restaurant from one screen</h1>
<p>What every page of the OrderOrange partner app does, in the order you will meet them: selling, orders and guests, your menu, money, your team, reports and setup. Screens are from the Saffron Grill House demo store.</p>
<div class="meta"><span><i>{count}</i> screens</span><span><i>{len(parts)}</i> sections</span><span>Works on phone, tablet and desktop</span></div></div>
{body}
</main>
<footer>OrderOrange · Partner app guide · September 2026. Numbers in the screens are demo data.</footer>'''
out = os.path.join('..', 'orderorange-partner-guide.html')
open(out, 'w', encoding='utf-8').write(page)
print('written', out, round(len(page) / 1e6, 2), 'MB,', count, 'screens')
